import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import EntityList from "./EntityList.js";

describe("EntityList", () => {
  describe("renderer", () => {
    it("lists its children in an ordered list in the table, by default", () => {
      render(
        <EntityList>
          <li>Layout</li>
          <li>Danger</li>
        </EntityList>,
      );
      const list = screen.getByRole("list");
      expect(list.tagName).toBe("OL");
      expect(list.className).toBe("items");
      expect(screen.getAllByRole("listitem")).toHaveLength(2);
    });

    it("lays its children in the published Cards group, two columns each", () => {
      render(
        <EntityList data-testid="list" renderer="cards">
          <div className="card">Layout</div>
        </EntityList>,
      );
      const cards = screen.getByTestId("list").querySelector(".ds.cards");
      expect(cards?.textContent).toBe("Layout");
      expect(cards?.getAttribute("style")).toContain("--card-span: 2");
    });

    it("draws no toolbar: the strip holds the switch and the count", () => {
      render(
        <EntityList data-testid="list">
          <li>Layout</li>
        </EntityList>,
      );
      const list = screen.getByTestId("list");
      expect(list.children).toHaveLength(1);
      expect(screen.queryByRole("button")).toBeNull();
    });
  });

  describe("empty", () => {
    it("stands the catalog's line in for no children", () => {
      render(<EntityList data-testid="list" renderer="cards" />);
      const list = screen.getByTestId("list");
      expect(list.querySelector(".empty")?.textContent).toBe(
        "Nothing to list.",
      );
      expect(list.querySelector(".ds.cards, .items")).toBeNull();
    });

    it("stands the line it is given in for no children", () => {
      render(<EntityList empty="No stations yet." />);
      expect(screen.getByText("No stations yet.").className).toBe("empty");
      expect(screen.queryByRole("list")).toBeNull();
    });
  });

  it("applies custom className and passes native props through", () => {
    render(<EntityList className="custom-class" data-testid="list" />);
    const list = screen.getByTestId("list");
    expect(list.className).toContain("ds entity-list");
    expect(list.className).toContain("custom-class");
  });
});
